    "SHV": "Interior",
    "MON": "Interior",
    "ALEX": "Interior",
    "PRSQ": "Interior",
    "JOHN": "Interior"
   }
  },
  {
   "name": "peak",
   "value": {
    "cci_confirmed": "cci_confirmed",
    "dual_unexplained": "dual_unexplained",
    "dual_ducting_unknown": "dual_ducting_unknown",
    "single_side": "one_side",
    "unpaired": "one_side"
   }
  },
  {
   "name": "vorder",
   "value": [
    "cci_confirmed",
    "dual_unexplained",
    "dual_ducting_unknown",
    "one_side"
   ]
  },
  {
   "name": "vlabel",
   "value": {
    "cci_confirmed": "CCI",
    "dual_unexplained": "UNEXPLAINED",
    "dual_ducting_unknown": "DUCTING UNKNOWN",
    "one_side": "ONE SIDE"
   }
  },
  {
   "name": "why",
   "value": {
    "Pacific coast": "Marine-layer inversion over the cold California Current: the most persistent ducting in the US, strongest in summer",
    "Mountain West": "Dry air and high terrain: ducting is rare, and the terrain blocks long paths",
    "Interior": "Night-time inversions under slow-moving high pressure east of the Rockies, peaking before dawn in late summer and autumn",
    "Great Lakes": "Warm air over cold lake water, mostly late spring and summer",
    "Atlantic coast": "Coastal ducts under high pressure and sea breezes along the seaboard, mostly late summer and autumn",
    "Gulf coast": "Warm, moist Gulf air over cooler shelf water, mostly spring and summer"
   }
  },
  {
   "name": "mode",
   "value": "climate",
   "on": [
    {
     "events": "@modeBtn:click",
     "update": "datum.mode"
    }
   ]
  },
  {
   "name": "top",
   "value": 26
  },
  {
   "name": "rowh",
   "value": 22
  },
  {
   "name": "r",
   "update": "max(30, min(height - top, width * 0.46) / 2 - 2)"
  },
  {
   "name": "cx",
   "update": "r + 2"
  },
  {
   "name": "cy",
   "update": "top + (height - top) / 2"
  },
  {
   "name": "lx",
   "update": "2 * r + 24"
  },
  {
   "name": "total",
   "update": "length(data('slices')) ? data('slices')[0].total : 0"
  }
 ],
 "data": [
  {
   "name": "vkey",
   "values": [
    {
     "i": 0,
     "label": "CCI",
     "color": "#FF6B5E"
    },
    {
     "i": 1,
     "label": "UNEXPLAINED",
     "color": "#E0A458"
    },
    {
     "i": 2,
     "label": "DUCTING UNKNOWN",
     "color": "#A88A4A"
    },
    {
     "i": 3,
     "label": "ONE SIDE",
     "color": "#5D7C91"
    }
   ]
  },
  {
   "name": "modes",
   "values": [
    {
     "mode": "tz",
     "label": "TIME ZONE",
     "o": 0
    },
    {
     "mode": "climate",
     "label": "DUCTING CLIMATE",
     "o": 1
    }
   ]
  },
  {
   "name": "lrfs",
   "format": {
    "property": "hits.hits"
   },
   "url": {
    "index": "lrf-coordinates",
    "body": {
     "size": 1000,
     "_source": [
      "code",
      "state"
     ],
     "query": {
      "match_all": {}
     }
    }
   },
   "transform": [
    {
     "type": "formula",
     "as": "code",
     "expr": "datum._source.code"
    },
    {
     "type": "formula",
     "as": "tz",
     "expr": "zoneLrf[datum.code] || zone[datum._source.state] || 'AK, HI, PR'"
    },
    {
     "type": "formula",
     "as": "climate",
     "expr": "climateLrf[datum.code] || climate[datum._source.state] || 'AK, HI, PR'"
    }
   ]
  },
  {
   "name": "epRaw",
   "format": {
    "property": "aggregations.l.buckets"
   },
   "url": {
    "index": "tropobeat-*",
    "body": {
     "size": 0,
     "aggs": {
      "l": {
       "terms": {
        "field": "tropobeat.lrf_codes",
        "size": 500
       },
       "aggs": {
        "e": {
         "terms": {
          "field": "tropobeat.correlation.episode.id",
          "size": 2000
         },
         "aggs": {
          "p": {
           "terms": {
            "field": "tropobeat.correlation.episode.peak_state",
            "size": 1
           }
          }
         }
        }
       }
      }
     },
     "query": {
      "bool": {
       "must": [
        "%dashboard_context-must_clause%",
        {
         "range": {
          "@timestamp": {
           "%timefilter%": true
          }
         }
        },
        {
         "term": {
          "metricset.name": "correlation"
         }
        }
       ],
       "must_not": [
        "%dashboard_context-must_not_clause%"
       ],
       "filter": [
        "%dashboard_context-filter_clause%"
       ]
      }
     }
    }
   }
  },
  {
   "name": "eps",
   "source": "epRaw",
   "transform": [
    {
     "type": "flatten",
     "fields": [
      "e.buckets"
     ],
     "as": [
      "ep"
     ]
    },
    {
     "type": "formula",
     "as": "lrf",
     "expr": "datum.key"
    },
    {
     "type": "formula",
     "as": "verdict",
     "expr": "datum.ep.p.buckets[0] && peak[datum.ep.p.buckets[0].key] || 'one_side'"
    },
    {
     "type": "lookup",
     "from": "lrfs",
     "key": "code",
     "fields": [
      "lrf"
     ],
     "values": [
      "tz",
      "climate"
     ],
     "default": "AK, HI, PR"
    },
    {
     "type": "formula",
     "as": "region",
     "expr": "mode == 'tz' ? datum.tz : datum.climate"
    }
   ]
  },
  {
   "name": "regionLrfs",
   "source": "eps",
   "transform": [
    {
     "type": "aggregate",
     "groupby": [
      "region",
      "lrf"
     ]
    },
    {
     "type": "aggregate",
     "groupby": [
      "region"
     ],
     "fields": [
      "lrf"
     ],
     "ops": [
      "values"
     ],
     "as": [
      "rows"
     ]
    },
    {
     "type": "formula",
     "as": "lrfs",
     "expr": "pluck(datum.rows, 'lrf')"
    }
   ]
  },
  {
   "name": "byRegion",
   "source": "eps",
   "transform": [
    {
     "type": "aggregate",
     "groupby": [
      "region"
     ],
     "fields": [
      "verdict"
     ],
     "ops": [
      "count"
     ],
     "as": [
      "n"
     ]
    }
   ]
  },
  {
   "name": "slices",
   "values": [
    {
     "mode": "tz",
     "region": "West",
     "o": 0
    },
    {
     "mode": "tz",
     "region": "Mountain",
     "o": 1
    },
    {
     "mode": "tz",
     "region": "Central",
     "o": 2
    },
    {
     "mode": "tz",
     "region": "East",
     "o": 3
    },
    {
     "mode": "tz",
     "region": "AK, HI, PR",
     "o": 4
    },
    {
     "mode": "climate",
     "region": "Pacific coast",
     "o": 0
    },
    {
     "mode": "climate",
     "region": "Mountain West",
     "o": 1
    },
    {
     "mode": "climate",
     "region": "Interior",
     "o": 2
    },
    {
     "mode": "climate",
     "region": "Great Lakes",
     "o": 3
    },
    {
     "mode": "climate",
     "region": "Atlantic coast",
     "o": 4
    },
    {
     "mode": "climate",
     "region": "Gulf coast",
     "o": 5
    },
    {
     "mode": "climate",
     "region": "AK, HI, PR",
     "o": 6
    }
   ],
   "transform": [
    {
     "type": "filter",
     "expr": "datum.mode == mode"
    },
    {
     "type": "lookup",
     "from": "byRegion",
     "key": "region",
     "fields": [
      "region"
     ],
     "values": [
      "n"
     ],
     "default": 0
    },
    {
     "type": "lookup",
     "from": "regionLrfs",
     "key": "region",
     "fields": [
      "region"
     ],
     "values": [
      "lrfs"
     ],
     "default": null
    },
    {
     "type": "filter",
     "expr": "datum.region != 'AK, HI, PR' || datum.n > 0"
    },
    {
     "type": "collect",
     "sort": {
      "field": "o"
     }
    },
    {
     "type": "joinaggregate",
     "fields": [
      "n"
     ],
     "ops": [
      "sum"
     ],
     "as": [
      "total"
     ]
    },
    {
     "type": "formula",
     "as": "share",
     "expr": "datum.total ? datum.n / datum.total : 0"
    },
    {
     "type": "formula",
     "as": "where",
     "expr": "datum.lrfs ? join(slice(datum.lrfs, 0, 5), ', ') + (length(datum.lrfs) > 5 ? ' +' + (length(datum.lrfs) - 5) : '') : ''"
    },
    {
     "type": "pie",
     "field": "n",
     "sort": false
    },
    {
     "type": "window",
     "ops": [
      "row_number"
     ],
     "as": [
      "row"
     ]
    }
   ]
  },
  {
   "name": "outer",
   "source": "eps",
   "transform": [
    {
     "type": "aggregate",
     "groupby": [
      "region",
      "verdict"
     ],
     "fields": [
      "verdict"
     ],
     "ops": [
      "count"
     ],
     "as": [
      "n"
     ]
    },
    {
     "type": "lookup",
     "from": "slices",
     "key": "region",
     "fields": [
      "region"
     ],
     "values": [
      "o",
      "total"
     ],
     "default": null
    },
    {
     "type": "filter",
     "expr": "datum.o != null"
    },
    {
     "type": "formula",
     "as": "vo",
     "expr": "indexof(vorder, datum.verdict)"
    },
    {
     "type": "collect",
     "sort": {
      "field": [
       "o",
       "vo"
      ]
     }
    },
    {
     "type": "pie",
     "field": "n",
     "sort": false
    }
   ]
  }
 ],
 "scales": [
  {
   "name": "color",
   "type": "ordinal",
   "domain": [
    "West",
    "Mountain",
    "Central",
    "East",
    "Pacific coast",
    "Mountain West",
    "Interior",
    "Great Lakes",
    "Atlantic coast",
    "Gulf coast",
    "AK, HI, PR"
   ],
   "range": [
    "#199e70",
    "#3987e5",
    "#008300",
    "#9085e9",
    "#9085e9",
    "#d55181",
    "#3987e5",
    "#008300",
    "#a35ac9",
    "#199e70",
    "#5D7C91"
   ]
  },
  {
   "name": "vcolor",
   "type": "ordinal",
   "domain": [
    "cci_confirmed",
    "dual_unexplained",
    "dual_ducting_unknown",
    "one_side"
   ],
   "range": [
    "#FF6B5E",
    "#E0A458",
    "#A88A4A",
    "#5D7C91"
   ]
  }
 ],
 "marks": [
  {
   "type": "text",
   "name": "modeBtn",
   "from": {
    "data": "modes"
   },
   "encode": {
    "update": {
     "x": {
      "signal": "width - (datum.o == 0 ? 136 : 0)"
     },
     "y": {
      "value": 10
     },
     "align": {
      "value": "right"
     },
     "text": {
      "field": "label"
     },
     "font": {
      "value": "ui-monospace,Menlo,Consolas,monospace"
     },
     "fontSize": {
      "value": 11
     },
     "fontWeight": {
      "signal": "datum.mode == mode ? 600 : 400"
     },
     "fill": {
      "signal": "datum.mode == mode ? '#E4EDF3' : '#8DA2B2'"
     },
     "cursor": {
      "value": "pointer"
     }
    },
    "hover": {
     "fill": {
      "value": "#E4EDF3"
     }
    }
   }
  },
  {
   "type": "rule",
   "from": {
    "data": "modes"
   },
   "encode": {
    "update": {
     "x": {
      "signal": "width - (datum.o == 0 ? 136 : 0) - length(datum.label) * 11 * 0.62"
     },
     "x2": {
      "signal": "width - (datum.o == 0 ? 136 : 0)"
     },
     "y": {
      "value": 14.5
     },
     "stroke": {
      "value": "#E4EDF3"
     },
     "opacity": {
      "signal": "datum.mode == mode ? 1 : 0"
     }
    }
   }
  },
  {
   "type": "text",
   "encode": {
    "update": {
     "x": {
      "signal": "width - 124"
     },
     "y": {
      "value": 10
     },
     "font": {
      "value": "ui-monospace,Menlo,Consolas,monospace"
     },
     "fontSize": {
      "value": 11
     },
     "fill": {
      "value": "#8DA2B2"
     },
     "text": {
      "value": "|"
     }
    }
   }
  },
  {
   "type": "arc",
   "from": {
    "data": "slices"
   },
   "encode": {
    "update": {
     "x": {
      "signal": "cx"
     },
     "y": {
      "signal": "cy"
     },
     "startAngle": {
      "field": "startAngle"
     },
     "endAngle": {
      "field": "endAngle"
     },
     "outerRadius": {
      "signal": "r * 0.72"
     },
     "innerRadius": {
      "signal": "r * 0.44"
     },
     "padAngle": {
      "value": 0.012
     },
     "cornerRadius": {
      "value": 2
     },
     "fill": {
      "scale": "color",
      "field": "region"
     },
     "opacity": {
      "value": 1
     },
     "tooltip": {
      "signal": "why[datum.region] && mode == 'climate' ? {title: datum.region, 'Ducting': why[datum.region], 'Episodes': datum.n + ' (' + format(datum.share, '.0%') + ')', 'LRFs': datum.where} : {title: datum.region, 'Episodes': datum.n + ' (' + format(datum.share, '.0%') + ')', 'LRFs': datum.where}"
     }
    },
    "hover": {
     "opacity": {
      "value": 0.8
     }
    }
   }
  },
  {
   "type": "arc",
   "from": {
    "data": "outer"
   },
   "encode": {
    "update": {
     "x": {
      "signal": "cx"
     },
     "y": {
      "signal": "cy"
     },
     "startAngle": {
      "field": "startAngle"
     },
     "endAngle": {
      "field": "endAngle"
     },
     "outerRadius": {
      "signal": "r"
     },
     "innerRadius": {
      "signal": "r * 0.75"
     },
     "padAngle": {
      "value": 0.012
     },
     "cornerRadius": {
      "value": 2
     },
     "fill": {
      "scale": "vcolor",
      "field": "verdict"
     },
     "opacity": {
      "value": 1
     },
     "tooltip": {
      "signal": "{title: datum.region + ' · ' + vlabel[datum.verdict], 'Episodes': datum.n + ' of ' + datum.total + ' (' + format(datum.n / datum.total, '.0%') + ')'}"
     }
    },
    "hover": {
     "opacity": {
      "value": 0.8
     }
    }
   }
  },
  {
   "type": "arc",
   "encode": {
    "update": {
     "x": {
      "signal": "cx"
     },
     "y": {
      "signal": "cy"
     },
     "startAngle": {
      "value": 0
     },
     "endAngle": {
      "signal": "2 * PI"
     },
     "outerRadius": {
      "signal": "r"
     },
     "innerRadius": {
      "signal": "r * 0.44"
     },
